    for(var i=0;i<28;i++){var key=new Date(start.getTime()+i*86400000).toISOString().slice(0,10),count=g&&g.days[key]||0;days.push('<span class="commit-dot level-'+Math.min(4,count===0?0:count<3?1:count<6?2:count<10?3:4)+'" title="'+key+' · '+count+' commit(s)"></span>');}
