    if(e.target.id==='kept-form'){e.preventDefault();await submitKept(e.target);return;}
    if(e.target.id==='recipe-link-form'){e.preventDefault();try{await HubTools.store([HubTools.item({id:HubTools.id(),kind:'link',title:e.target.elements.title.value,url:e.target.elements.url.value})]);await loadKept();toast('Lien enregistré sur cet appareil.');}catch(err){$('#link-error').textContent=err.message;}return;}
    if(e.target.id==='github-form'){e.preventDefault();if(state.githubBusy)return;if(state.githubAttempt&&Date.now()-state.githubAttempt<60000){toast('Patiente une minute entre deux actualisations.');return;}var user=e.target.elements.username.value.trim();if(!/^[a-z0-9](?:[a-z0-9-]{0,37}[a-z0-9])?$/i.test(user)){toast('Indique un nom GitHub valide, sans URL.');return;}state.githubUser=user;save('githubUser',user);state.github=null;save('github',null);await loadGithub(true);}
    if(e.target.id==='shopping-form'){e.preventDefault();var label=e.target.elements.item.value.trim();if(label){state.shopping.push({key:'manual:'+Date.now(),label:label,recipe:'À ne pas oublier',done:false});save('shopping',state.shopping);renderOverlay();$('#shopping-item').focus();}}
    if(e.target.id==='add-task'){e.preventDefault();var input=e.target.elements.content,content=input.value.trim();if(!content)return;try{if(state.status&&state.status.todoist.connected){await api('/api/tasks',{content:content});await refresh();}else{state.tasks.push({id:'local-'+Date.now(),content:content,priority:1});save('tasks',state.tasks);render();}$('#task-content').focus();}catch(err){toast(err.message);}}
    if(e.target.id==='import-recipe'){e.preventDefault();try{var file=$('#recipe-file').files[0],raw=file?await file.text():$('#recipe-json').value;if(raw.length>250000)throw new Error('Le fichier doit faire moins de 250 Ko.');var manual={'@type':'Recipe',name:$('#recipe-title').value,recipeIngredient:$('#recipe-ingredients').value.split('\n').filter(Boolean),recipeInstructions:$('#recipe-steps').value.split('\n').filter(Boolean),totalTime:'PT'+($('#recipe-time').value||30)+'M',recipeYield:$('#recipe-servings').value||2,url:$('#recipe-source').value};var rec=normalizeRecipe(raw.trim()?JSON.parse(raw):manual);state.recipes.push(rec);save('recipes',state.recipes.filter(function(r){return r.id.indexOf('import-')===0;}));closeModal();state.page='kitchen';render();toast('Recette enregistrée.');}catch(err){$('#import-error').textContent=err.message||'Le JSON ne contient pas une recette valide.';}}
