  document.addEventListener('keydown',function(e){inputMode='keyboard';document.documentElement.classList.add('keyboard-input');resetIdle();if(e.key==='Escape'){if(state.sleep){state.sleep=false;renderOverlay();}else closeModal();}if(e.key==='Tab'&&state.modal){var nodes=Array.from(document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea,.modal a')).filter(function(n){return !n.disabled;});var first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
